(2022599, 277265, 30982, '<td valign="top">It''s definitely a "burst" but a bit lacking in the color part.</td>', 'It''s definitely a "burst" but a bit lacking in the color part.', '2006-01-10 16:50:07.000000', NULL, 1),
(2022602, 278466, 30982, '<td valign="top">Lacks a bit in general interest - then again, maybe pictures of condiments just aren''t my thing.</td>', 'Lacks a bit in general interest - then again, maybe pictures of condiments just aren''t my thing.', '2006-01-10 16:51:28.000000', NULL, 1),
