INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2034468, 278386, 75713, '<td valign="top">what a beautiful photo..... the colors burst but are also fragile.. excellent</td>', 'what a beautiful photo..... the colors burst but are also fragile.. excellent', '2006-01-13 21:57:50.000000', NULL, 1),
