(2034472, 277275, 75713, '<td valign="top">reallu interesting photo... colors great and the composition really caught my eye</td>', 'reallu interesting photo... colors great and the composition really caught my eye', '2006-01-13 21:59:05.000000', NULL, 1),
(2034474, 278543, 75713, '<td valign="top">my mouth is puckering here - very nice</td>', 'my mouth is puckering here - very nice', '2006-01-13 21:59:35.000000', NULL, 1),
