(2035576, 276402, 22734, '<td valign="top">A rainbow is always a burst color and with this low key image this one is a real beauty.</td>', 'A rainbow is always a burst color and with this low key image this one is a real beauty.', '2006-01-14 11:04:28.000000', NULL, 1),
(2035579, 278354, 22734, '<td valign="top">Beautiful eyes and what an expression. The red looks nice!</td>', 'Beautiful eyes and what an expression. The red looks nice!', '2006-01-14 11:06:08.000000', NULL, 1),
(2035582, 278341, 22734, '<td valign="top">A lovely use of dof to bring out this poetic burst.</td>', 'A lovely use of dof to bring out this poetic burst.', '2006-01-14 11:07:08.000000', NULL, 1),
(2035584, 278199, 22734, '<td valign="top">Lovely image and great isolation of subject to bring out the color.</td>', 'Lovely image and great isolation of subject to bring out the color.', '2006-01-14 11:08:33.000000', NULL, 1),
(2035586, 278525, 42638, '<td valign="top">Very nice, Good focus and the colors are great. Love the clear eyes, good composition.</td>', 'Very nice, Good focus and the colors are great. Love the clear eyes, good composition.', '2006-01-14 11:08:59.000000', NULL, 1),
(2035588, 278060, 22734, '<td valign="top">This guy is just lovely surrounded in red. The image makes me want to pet him.</td>', 'This guy is just lovely surrounded in red. The image makes me want to pet him.', '2006-01-14 11:09:28.000000', NULL, 1),
(2035601, 278386, 42638, '<td valign="top">Beautiful Picture, a bit grainy but I love the colors and use of space. It really pops out. Nicely done!</td>', 'Beautiful Picture, a bit grainy but I love the colors and use of space. It really pops out. Nicely done!', '2006-01-14 11:18:21.000000', NULL, 1),
(2035603, 278041, 42638, '<td valign="top">Love the idea with this one, good focus on the face, the almost ''misty'' colors are great. Nicely done!</td>', 'Love the idea with this one, good focus on the face, the almost ''misty'' colors are great. Nicely done!', '2006-01-14 11:19:37.000000', NULL, 1),
(2035608, 277265, 42638, '<td valign="top">Nice idea and title. Love the pixel effect. The more I look at this the more it seems to almost radiate. Interesting picture.</td>', 'Nice idea and title. Love the pixel effect. The more I look at this the more it seems to almost radiate. Interesting picture.', '2006-01-14 11:21:21.000000', NULL, 1),
(2035610, 276712, 42638, '<td valign="top">Very nice colors, The subject is a bit too far off the picture and with so much white space, it makes me feel like the camera shifted when you took it. Good focus.</td>', 'Very nice colors, The subject is a bit too far off the picture and with so much white space, it makes me feel like the camera shifted when you took it. Good focus.', '2006-01-14 11:22:53.000000', NULL, 1),
(2035611, 278443, 42638, '<td valign="top">Nice detail here, interesting effect with the petals.</td>', 'Nice detail here, interesting effect with the petals.', '2006-01-14 11:23:48.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2035614, 277088, 42638, '<td valign="top">Very nice concept, good focus. I think it might be even stronger if the background was whiter, the yellow/orange tends to mute the bright red.</td>', 'Very nice concept, good focus. I think it might be even stronger if the background was whiter, the yellow/orange tends to mute the bright red.', '2006-01-14 11:24:57.000000', NULL, 1),
(2035620, 276343, 42638, '<td valign="top">Wow, love how they almost come right out at you. Good concept and execution, Nicely done!</td>', 'Wow, love how they almost come right out at you. Good concept and execution, Nicely done!', '2006-01-14 11:27:25.000000', NULL, 1),
(2035677, 278269, 48245, '<td valign="top">wow</td>', 'wow', '2006-01-14 12:27:11.000000', NULL, 1),
(2035682, 278473, 40819, '<td valign="top">Oh this is so interesting, the only thing I would have done is remove a little red so the skin looked whiter the lips are just so good I can understand you would be hesitent to do that. Great image composition too.</td>', 'Oh this is so interesting, the only thing I would have done is remove a little red so the skin looked whiter the lips are just so good I can understand you would be hesitent to do that. Great image composition too.', '2006-01-14 12:28:56.000000', NULL, 1),
