(2035770, 278226, 22734, '<td valign="top">A very sensuous splash of color.</td>', 'A very sensuous splash of color.', '2006-01-14 13:46:41.000000', NULL, 1),
(2035773, 278198, 22734, '<td valign="top">Very nice and even better if old sqeezed tubes were used. Nethertheless a nice splash of colors.</td>', 'Very nice and even better if old sqeezed tubes were used. Nethertheless a nice splash of colors.', '2006-01-14 13:48:11.000000', NULL, 1),
(2035775, 278592, 22734, '<td valign="top">Just beautiful!</td>', 'Just beautiful!', '2006-01-14 13:48:29.000000', NULL, 1),
