(2039547, 275872, 48717, '<td valign="top">Wonderful color, not sure what it is, but the focus and lighting are perfect.</td>', 'Wonderful color, not sure what it is, but the focus and lighting are perfect.', '2006-01-15 22:29:51.000000', NULL, 1),
(2039549, 278178, 12160, '<td valign="top">The lighting is awesome. Well-composed image. 8</td>', 'The lighting is awesome. Well-composed image. 8', '2006-01-15 22:30:38.000000', NULL, 1),
